// === Tab: mySketch ===
OPC.slider('radius',200,50,500,1)
OPC.slider('viewAngle',60,-360,360,1)
OPC.slider('angle1',0,-360,360,1)
OPC.slider('angle2',45,0,180,1)

function setup() {
	createCanvas(windowWidth, windowHeight);
	angleMode(DEGREES)
	background(0);
}

function draw() {
	background(0);
	push()
	translate(width/2,height/2)

	stroke(255)
	noFill()
	strokeWeight(4)
	point(0,0)

	strokeWeight(2)

	stroke("yellow")

	line(0,0,cos(angle1)*radius*cos(angle2),-radius*sin(angle2)*sin(viewAngle) + sin(angle1)*radius*cos(viewAngle)*cos(angle2))

	strokeWeight(4)
	point(cos(angle1)*radius*cos(angle2),-radius*sin(angle2)*sin(viewAngle) + sin(angle1)*radius*cos(viewAngle)*cos(angle2))
	stroke(255)
	//輔助線
	strokeWeight(1)
	setLineDash([5,5])
	arc(0,0,radius*2,radius*2*cos(viewAngle),180,360)

	line(0,0,cos(angle1)*radius,sin(angle1)*radius*cos(viewAngle))
	push()
	// stroke(255,0,0)
	// setLineDash([0])
	// line(0,0,0,-radius*sin(angle2)*sin(viewAngle))
	// line(0,-radius*sin(angle2)*sin(viewAngle),
	// 		 0 + cos(angle1)*radius*cos(angle2),
	// 		 -radius*sin(angle2)*sin(viewAngle) + sin(angle1)*radius*cos(viewAngle)*cos(angle2))
	pop()

	setLineDash([0])
	arc(0,0,radius*2,radius*2*cos(viewAngle),0,180)
	arc(0,0,radius*2,radius*2,180,360)
	line(0,0,radius,0)
	line(0,0,0,-radius*sin(viewAngle))
	strokeWeight(4)
	point(0,-radius*sin(viewAngle))

	pop()
}

function setLineDash(list) {
  drawingContext.setLineDash(list);
}

function lineDashOffset(value){
	drawingContext.lineDashOffset = value;
}

